INSERT INTO `products` (`id`, `category_id`, `brand_id`, `name`, `description`, `product_specification`, `how_to_order`, `return_policy`, `key_features`, `club_point`, `product_type`, `product_cost`, `product_value`, `discount_price`, `product_code`, `img_path`, `img_path_2`, `img_path_3`, `img_path_4`, `img_path_5`, `img_path_6`, `max_purchase_limit`, `stock_status`, `stock_quantity`, `xxs_stock`, `xs_stock`, `s_stock`, `m_stock`, `l_stock`, `xl_stock`, `xxl_stock`, `xxxl_stock`, `xxxxl_stock`, `total_sell`, `colors`, `status`, `created_by`, `updated_by`, `created_at`, `updated_at`) VALUES
(34, 5, 1, 'Chia Seeds/চিয়া সীড-হানিজুস Combo Pack (লিচু ফুলের মধু+চিয়া সীড)', '<p style=\"border: 0px solid rgb(229, 231, 235); --tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-scroll-snap-strictness: proximity; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgba(59,130,246,.5019607843137255); --tw-ring-offset-shadow: 0 0 transparent; --tw-ring-shadow: 0 0 transparent; --tw-shadow: 0 0 transparent; --tw-shadow-colored: 0 0 transparent; -webkit-tap-highlight-color: rgba(0, 0, 0, 0); margin-top: 0.75em; margin-bottom: 0.75em; color: rgb(102, 102, 102); font-family: &quot;Basic Commercial&quot;, sans-serif; font-size: 16px;\">স্বাস্থ্য, পুষ্টি এবং রোগ প্রতিরোধ ক্ষমতা বাড়াতে শুধুমাত্র একটি খাবারই যথেষ্ট নয়! চাই সঠিক পরিমাণে সঠিক পুষ্টি সমৃদ্ধ খাবার প্রয়োজন। চিয়া সিড একটি পুষ্টিকর খাবার। এতে দুধের চেয়ে ৫ গুণ বেশি ক্যালসিয়াম, কমলার চেয়ে ৭ গুণ বেশি ভিটামিন সি, পালং শাকের চেয়ে ৩ গুণ বেশি আয়রন, কলার চেয়ে ২ গুণ বেশি পটাসিয়াম, ডিমের চেয়ে ৩ গুণ বেশি প্রোটিন এবং স্যালমনের চেয়ে ৪ গুণ বেশি ওমেগা-3 রয়েছে।&nbsp;<br style=\"border: 0px solid rgb(229, 231, 235); --tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-scroll-snap-strictness: proximity; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgba(59,130,246,.5019607843137255); --tw-ring-offset-shadow: 0 0 transparent; --tw-ring-shadow: 0 0 transparent; --tw-shadow: 0 0 transparent; --tw-shadow-colored: 0 0 transparent; -webkit-tap-highlight-color: rgba(0, 0, 0, 0);\"><br style=\"border: 0px solid rgb(229, 231, 235); --tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-scroll-snap-strictness: proximity; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgba(59,130,246,.5019607843137255); --tw-ring-offset-shadow: 0 0 transparent; --tw-ring-shadow: 0 0 transparent; --tw-shadow: 0 0 transparent; --tw-shadow-colored: 0 0 transparent; -webkit-tap-highlight-color: rgba(0, 0, 0, 0);\">অন্যদিকে, আয়ুর্বেদিক ও ইউনানী চিকিৎসায় মধুকে মহৌষধ বলা হয়। এটি মানব দেহে ইমিউনিটি বা রোগ প্রতিরোধ ক্ষমতা বৃদ্ধি করে । হৃদরোগ প্রতিরোধ, রক্তনালী প্রসারিত করে সঞ্চালন উন্নত করা এবং হৃৎপিণ্ডের পেশীগুলির কার্যকলাপ বৃদ্ধি সহ এর আরও অনেক পুষ্টিগুন রয়েছে।<br style=\"border: 0px solid rgb(229, 231, 235); --tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-scroll-snap-strictness: proximity; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgba(59,130,246,.5019607843137255); --tw-ring-offset-shadow: 0 0 transparent; --tw-ring-shadow: 0 0 transparent; --tw-shadow: 0 0 transparent; --tw-shadow-colored: 0 0 transparent; -webkit-tap-highlight-color: rgba(0, 0, 0, 0);\"><br style=\"border: 0px solid rgb(229, 231, 235); --tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-scroll-snap-strictness: proximity; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgba(59,130,246,.5019607843137255); --tw-ring-offset-shadow: 0 0 transparent; --tw-ring-shadow: 0 0 transparent; --tw-shadow: 0 0 transparent; --tw-shadow-colored: 0 0 transparent; -webkit-tap-highlight-color: rgba(0, 0, 0, 0);\">তাই চিয়া সিড ও লিচু ফুলের মধু নিয়ে Ghorerbazar-এর চিয়া সিড হানিজুস প্যাকেজটি আপনার সুস্থ্যতা ও পুষ্টির জন্য হতে পারে দারুন কার্যকারী!</p><p style=\"border: 0px solid rgb(229, 231, 235); --tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y